  @Name_575e0d07aeb2 = N'Orders — Create Provider Subscriptions (daily)'
SET
  @Description_575e0d07aeb2 = N'Creates the missing gateway subscriptions for active auto-renewing subscriptions on accounts whose gateway bills renewals (BillsSubscriptions on), and records each gateway id so Orders'' renewal jobs skip it. Retries what the checkout could not do, creates terms that start later once their first charge fits, and backfills buyers from before the switch. Ships disabled, set to Preview and capped at 25 a pass: enable it, read the Outcomes on the run, then set Preview to false. REQUIRED wherever an account has BillsSubscriptions on: a host that turns the switch on must set this job Active, read one preview run, then set Preview to false. Nothing checks that it did. Until then a checkout that could not hand a subscription over (GatewayFault, NotRecorded) leaves Orders renewing it, while the gateway may bill it too.'
SET
  @CronExpression_575e0d07aeb2 = N'0 45 2 * * *'
